-- Phase 4D: explicit, service-level financial eligibility and route-facing exclusion.
alter table app_private.outbox_events drop constraint outbox_events_producer_module_check;
alter table app_private.outbox_events add constraint outbox_events_producer_module_check check (producer_module in ('identity-access','clients','service-addresses','service-configuration','geography','workforce','vehicles','daily-roster','routes','route-operations','vehicle-tracking','operational-issues','needs-attention','communications','integrations','configuration','reporting','audit','system-health','platform-runtime','operational-intelligence','website-intake','client-migration','accounting','financial-eligibility'));

insert into app_private.permissions(permission_key,description) values
 ('financial_eligibility.read','Read service financial eligibility'),('financial_eligibility.review','Review policy evidence and impacts'),('financial_eligibility.hold','Place a service on financial hold'),('financial_eligibility.release','Release a financial hold'),('financial_eligibility.override','Manage financial eligibility overrides'),('financial_eligibility.reevaluate','Request policy reevaluation') on conflict do nothing;
insert into app_private.role_permissions(role_id,permission_key) select r.role_id,p.permission_key from app_private.roles r cross join app_private.permissions p where r.role_key='director_admin' and p.permission_key like 'financial_eligibility.%' on conflict do nothing;
insert into app_private.role_permissions(role_id,permission_key) select r.role_id,p.permission_key from app_private.roles r cross join app_private.permissions p where r.role_key='operations_manager' and p.permission_key like 'financial_eligibility.%' on conflict do nothing;
insert into app_private.role_permissions(role_id,permission_key) select r.role_id,p.permission_key from app_private.roles r join app_private.permissions p on p.permission_key in('financial_eligibility.read','financial_eligibility.review','financial_eligibility.hold','financial_eligibility.release','financial_eligibility.reevaluate') where r.role_key='office_admin' on conflict do nothing;

insert into app_private.configuration_definitions(configuration_key,description,value_type,is_required,default_value) values
 ('financial-eligibility.policy-version','Active policy version','string',true,'"2026-08-v1"'),('financial-eligibility.hold-account-statuses','Statuses recommending hold','json',true,'{"statuses":["seriously_overdue"]}'),('financial-eligibility.minimum-overdue-days','Minimum overdue age','number',true,'60'),('financial-eligibility.minimum-overdue-amount-minor','Minimum overdue amount','number',true,'1'),('financial-eligibility.stale-tolerance-hours','Maximum accounting evidence age','number',true,'48'),('financial-eligibility.auto-hold-enabled','Allow automatic hold activation','boolean',true,'false'),('financial-eligibility.auto-release-enabled','Allow automatic hold release','boolean',true,'false') on conflict do nothing;

create table app_private.financial_eligibility_policy_versions(financial_eligibility_policy_version_id uuid primary key default gen_random_uuid(),policy_key text not null,version text not null,lifecycle_status text not null default 'active' check(lifecycle_status in('draft','active','retired')),configuration jsonb not null check(jsonb_typeof(configuration)='object'),created_by uuid references auth.users,created_at timestamptz not null default now(),unique(policy_key,version));
insert into app_private.financial_eligibility_policy_versions(policy_key,version,configuration) values('default','2026-08-v1','{"holdAccountStatuses":["seriously_overdue"],"minimumOverdueDays":60,"minimumOverdueAmountMinor":1,"staleToleranceHours":48,"autoHoldEnabled":false,"autoReleaseEnabled":false,"manualReviewOnUnreconciled":true}');
create table app_private.financial_eligibility_decisions(financial_eligibility_decision_id uuid primary key default gen_random_uuid(),client_id uuid not null references app_private.clients,client_service_id uuid not null references app_private.client_services,service_region_id uuid not null references app_private.service_regions,accounting_snapshot_client_id uuid references app_private.client_accounting_snapshots(client_id),policy_version_id uuid not null references app_private.financial_eligibility_policy_versions,decision_version integer not null check(decision_version>0),decision_status text not null check(decision_status in('eligible','warning','hold_recommended','held','manual_review','unknown')),reason_code text not null,evidence jsonb not null check(jsonb_typeof(evidence)='object'),effective_from timestamptz not null default now(),effective_until timestamptz,decision_source text not null check(decision_source in('policy','manual_hold','manual_release','override')),actor_id uuid references auth.users,correlation_id uuid not null,supersedes_decision_id uuid references app_private.financial_eligibility_decisions,created_at timestamptz not null default now(),unique(client_service_id,decision_version),check(effective_until is null or effective_until>effective_from));
create unique index financial_decision_current_idx on app_private.financial_eligibility_decisions(client_service_id) where effective_until is null;
create index financial_decision_region_status_idx on app_private.financial_eligibility_decisions(service_region_id,decision_status,created_at desc);
create table app_private.financial_eligibility_overrides(financial_eligibility_override_id uuid primary key default gen_random_uuid(),client_service_id uuid not null references app_private.client_services,override_status text not null check(override_status in('eligible','held','manual_review')),reason text not null check(length(btrim(reason))>=3),effective_from timestamptz not null default now(),effective_until timestamptz,version integer not null default 1,created_by uuid not null references auth.users,created_at timestamptz not null default now(),revoked_at timestamptz,revoked_by uuid references auth.users,revoke_reason text,check(effective_until is null or effective_until>effective_from));
create unique index financial_override_current_idx on app_private.financial_eligibility_overrides(client_service_id) where revoked_at is null;
create table app_private.financial_holds(financial_hold_id uuid primary key default gen_random_uuid(),client_service_id uuid not null references app_private.client_services,source_decision_id uuid not null references app_private.financial_eligibility_decisions,lifecycle_status text not null check(lifecycle_status in('proposed','active','released','cancelled','superseded')),reason_code text not null,effective_from timestamptz not null default now(),effective_until timestamptz,created_by uuid references auth.users,created_at timestamptz not null default now(),released_at timestamptz,released_by uuid references auth.users,release_reason text);
create unique index financial_hold_active_idx on app_private.financial_holds(client_service_id) where lifecycle_status='active';
create table app_private.financial_eligibility_jobs(financial_eligibility_job_id uuid primary key default gen_random_uuid(),scope_type text not null check(scope_type in('client','service','region','stale_review')),scope_id uuid,lifecycle_status text not null default 'pending' check(lifecycle_status in('pending','running','succeeded','partial','failed','cancelled')),idempotency_key text not null unique,correlation_id uuid not null,initiated_by uuid references auth.users,processed_count integer not null default 0,changed_count integer not null default 0,failure_count integer not null default 0,created_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz,safe_failure text);

alter table app_private.financial_eligibility_policy_versions enable row level security;alter table app_private.financial_eligibility_decisions enable row level security;alter table app_private.financial_eligibility_overrides enable row level security;alter table app_private.financial_holds enable row level security;alter table app_private.financial_eligibility_jobs enable row level security;
revoke all on app_private.financial_eligibility_policy_versions,app_private.financial_eligibility_decisions,app_private.financial_eligibility_overrides,app_private.financial_holds,app_private.financial_eligibility_jobs from public,anon,authenticated;
grant all on app_private.financial_eligibility_policy_versions,app_private.financial_eligibility_decisions,app_private.financial_eligibility_overrides,app_private.financial_holds,app_private.financial_eligibility_jobs to service_role;
alter table app_private.unassigned_route_services drop constraint unassigned_route_services_reason_code_check;
alter table app_private.unassigned_route_services add constraint unassigned_route_services_reason_code_check check(reason_code in('missing_coordinates','missing_territory','no_eligible_team','capacity_exceeded','working_window_exceeded','invalid_service_configuration','unsupported_cadence','roster_assignment_unavailable','financial_hold'));

create or replace function app_private.financial_require(p_actor uuid,p_permission text,p_region uuid)returns void language plpgsql security definer set search_path='' as $$begin if not app_private.user_has_region_permission(p_actor,p_permission,p_region)then raise exception 'region_denied' using errcode='42501';end if;end$$;
create or replace function app_private.financial_policy_preview(p_service uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare svc app_private.client_services%rowtype;s app_private.client_accounting_snapshots%rowtype;ae app_private.accounting_status_exceptions%rowtype;o app_private.financial_eligibility_overrides%rowtype;p app_private.financial_eligibility_policy_versions%rowtype;status text;reason text;effective_account text;stale boolean;region uuid;begin select * into svc from app_private.client_services where client_service_id=p_service;if svc.client_service_id is null then raise exception 'not_found' using errcode='P0002';end if;select service_region_id into region from app_private.service_configurations where client_service_id=p_service and effective_to is null order by effective_from desc limit 1;select * into p from app_private.financial_eligibility_policy_versions where lifecycle_status='active' order by created_at desc limit 1;select * into s from app_private.client_accounting_snapshots where client_id=svc.client_id;select * into ae from app_private.accounting_status_exceptions where client_id=svc.client_id and revoked_at is null and(effective_until is null or effective_until>now());select * into o from app_private.financial_eligibility_overrides where client_service_id=p_service and revoked_at is null and(effective_until is null or effective_until>now());stale:=s.client_id is null or now()>s.stale_after;effective_account:=coalesce(ae.override_status,s.derived_status,'unknown');if o.financial_eligibility_override_id is not null then status:=o.override_status;reason:='manual_override';elsif s.client_id is null then status:='unknown';reason:='accounting_missing';elsif stale then status:='manual_review';reason:='accounting_stale';elsif s.reconciliation_status<>'mapped' then status:='manual_review';reason:='accounting_unreconciled';elsif ae.override_status='manual_review' then status:='manual_review';reason:='accounting_exception';elsif effective_account='current' then status:='eligible';reason:='account_current';elsif effective_account='due_soon' then status:='warning';reason:='account_due_soon';elsif effective_account='overdue' then status:='warning';reason:='account_overdue';elsif effective_account='seriously_overdue' and s.days_overdue>=(p.configuration->>'minimumOverdueDays')::integer and s.overdue_outstanding_minor>=(p.configuration->>'minimumOverdueAmountMinor')::bigint then status:=case when(p.configuration->>'autoHoldEnabled')::boolean then'held'else'hold_recommended'end;reason:='serious_overdue_threshold';else status:='unknown';reason:='account_status_unknown';end if;return jsonb_build_object('clientId',svc.client_id,'clientServiceId',p_service,'serviceRegionId',region,'policyVersionId',p.financial_eligibility_policy_version_id,'policyVersion',p.version,'suggestedStatus',status,'reasonCode',reason,'wouldHold',status='held','inputs',jsonb_build_object('accountStatus',effective_account,'daysOverdue',s.days_overdue,'overdueAmountMinor',s.overdue_outstanding_minor,'freshness',case when stale then'stale'else'current'end,'reconciliationState',coalesce(s.reconciliation_status,'missing'),'accountingException',ae.accounting_status_exception_id is not null,'financialOverride',o.financial_eligibility_override_id is not null));end$$;
create or replace function app_private.financial_route_contract(p_service uuid)returns jsonb language sql stable security definer set search_path='' as $$select coalesce((select jsonb_build_object('eligibleForCollection',decision_status<>'held','decisionStatus',decision_status,'reasonCode',case when decision_status='held'then'financial_hold'else reason_code end,'freshness',coalesce(evidence->'inputs'->>'freshness','unknown'),'effectiveTimestamp',effective_from,'decisionVersion',decision_version)from app_private.financial_eligibility_decisions where client_service_id=p_service and effective_until is null order by decision_version desc limit 1),jsonb_build_object('eligibleForCollection',false,'decisionStatus','unknown','reasonCode','financial_status_unknown','freshness','unknown','decisionVersion',0))$$;

create or replace function app_private.financial_route_impact(p_service uuid,p_mark_stale boolean default false)returns jsonb language plpgsql security definer set search_path='' as $$declare stale_count integer:=0;published_count integer;operation_count integer;begin if p_mark_stale then update app_private.route_versions v set is_stale=true,stale_reason='financial_eligibility_changed',updated_at=now()where v.version_status in('draft','ready')and exists(select 1 from app_private.planned_route_stops s where s.route_version_id=v.route_version_id and s.client_service_id=p_service);get diagnostics stale_count=row_count;end if;select count(*)into published_count from app_private.planned_route_stops s join app_private.route_versions v using(route_version_id)where s.client_service_id=p_service and v.version_status='published';select count(*)into operation_count from app_private.route_operation_stops s join app_private.planned_route_stops ps on ps.planned_route_stop_id=s.source_planned_route_stop_id join app_private.route_operations o using(route_operation_id)where ps.client_service_id=p_service and o.lifecycle_status not in('completed','cancelled','superseded','archived');return jsonb_build_object('draftReadyMarkedStale',stale_count,'publishedRoutesProtected',published_count,'activeOperationsProtected',operation_count,'reviewRequired',published_count+operation_count>0);end$$;
create or replace function app_private.financial_apply_decision(p_service uuid,p_status text,p_reason text,p_source text,p_actor uuid,p_correlation uuid,p_evidence jsonb)returns app_private.financial_eligibility_decisions language plpgsql security definer set search_path='' as $$declare old app_private.financial_eligibility_decisions%rowtype;n app_private.financial_eligibility_decisions%rowtype;svc app_private.client_services%rowtype;region uuid;policy uuid;impact jsonb;begin select * into svc from app_private.client_services where client_service_id=p_service;select service_region_id into region from app_private.service_configurations where client_service_id=p_service and effective_to is null order by effective_from desc limit 1;select financial_eligibility_policy_version_id into policy from app_private.financial_eligibility_policy_versions where lifecycle_status='active' order by created_at desc limit 1;select * into old from app_private.financial_eligibility_decisions where client_service_id=p_service and effective_until is null for update;if old.financial_eligibility_decision_id is not null and old.decision_status=p_status and old.reason_code=p_reason and old.evidence=p_evidence then return old;end if;update app_private.financial_eligibility_decisions set effective_until=now()where financial_eligibility_decision_id=old.financial_eligibility_decision_id;insert into app_private.financial_eligibility_decisions(client_id,client_service_id,service_region_id,accounting_snapshot_client_id,policy_version_id,decision_version,decision_status,reason_code,evidence,decision_source,actor_id,correlation_id,supersedes_decision_id)values(svc.client_id,p_service,region,case when exists(select 1 from app_private.client_accounting_snapshots where client_id=svc.client_id)then svc.client_id end,policy,coalesce(old.decision_version,0)+1,p_status,p_reason,p_evidence,p_source,p_actor,p_correlation,old.financial_eligibility_decision_id)returning * into n;impact:=app_private.financial_route_impact(p_service,true);insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('financial-eligibility','FinancialEligibility.DecisionChanged',1,'client-service',p_service,jsonb_build_object('clientServiceId',p_service,'decisionId',n.financial_eligibility_decision_id,'status',p_status,'reasonCode',p_reason,'version',n.decision_version),p_correlation,case when p_actor is null then'system'else'user'end,p_actor::text,now());return n;end$$;

create or replace function api.financial_eligibility_simulate(p_actor uuid,p_service uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare p jsonb;begin p:=app_private.financial_policy_preview(p_service);perform app_private.financial_require(p_actor,'financial_eligibility.review',(p->>'serviceRegionId')::uuid);return p||jsonb_build_object('committed',false);end$$;
create or replace function api.financial_eligibility_reevaluate(p_actor uuid,p_service uuid,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare p jsonb;n app_private.financial_eligibility_decisions%rowtype;begin p:=app_private.financial_policy_preview(p_service);perform app_private.financial_require(p_actor,'financial_eligibility.reevaluate',(p->>'serviceRegionId')::uuid);n:=app_private.financial_apply_decision(p_service,p->>'suggestedStatus',p->>'reasonCode','policy',p_actor,p_correlation,p);insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('financial_eligibility.reevaluated',p_actor,'financial-eligibility','client-service',p_service,p_correlation,jsonb_build_object('decisionId',n.financial_eligibility_decision_id,'status',n.decision_status));return to_jsonb(n)||jsonb_build_object('routeImpact',app_private.financial_route_impact(p_service,false));end$$;
create or replace function api.financial_eligibility_hold(p_actor uuid,p_service uuid,p_reason text,p_expected_version integer,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare p jsonb;cur app_private.financial_eligibility_decisions%rowtype;n app_private.financial_eligibility_decisions%rowtype;h app_private.financial_holds%rowtype;begin if length(btrim(coalesce(p_reason,'')))<3 then raise exception 'reason_required' using errcode='22023';end if;p:=app_private.financial_policy_preview(p_service);perform app_private.financial_require(p_actor,'financial_eligibility.hold',(p->>'serviceRegionId')::uuid);select * into cur from app_private.financial_eligibility_decisions where client_service_id=p_service and effective_until is null;if coalesce(cur.decision_version,0)<>p_expected_version then raise exception 'stale_financial_decision' using errcode='40001';end if;n:=app_private.financial_apply_decision(p_service,'held','manual_financial_hold','manual_hold',p_actor,p_correlation,p||jsonb_build_object('manualReason',p_reason));insert into app_private.financial_holds(client_service_id,source_decision_id,lifecycle_status,reason_code,created_by)values(p_service,n.financial_eligibility_decision_id,'active','manual_financial_hold',p_actor)returning * into h;insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('financial_eligibility.hold_activated',p_actor,'financial-eligibility','client-service',p_service,p_correlation,jsonb_build_object('decisionId',n.financial_eligibility_decision_id,'holdId',h.financial_hold_id,'reason',p_reason));insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('financial-eligibility','FinancialEligibility.HoldActivated',1,'client-service',p_service,jsonb_build_object('clientServiceId',p_service,'decisionId',n.financial_eligibility_decision_id,'holdId',h.financial_hold_id),p_correlation,'user',p_actor::text,now());return to_jsonb(n)||jsonb_build_object('hold',to_jsonb(h),'routeImpact',app_private.financial_route_impact(p_service,false));end$$;
create or replace function api.financial_eligibility_release(p_actor uuid,p_service uuid,p_reason text,p_expected_version integer,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare p jsonb;cur app_private.financial_eligibility_decisions%rowtype;n app_private.financial_eligibility_decisions%rowtype;begin if length(btrim(coalesce(p_reason,'')))<3 then raise exception 'reason_required' using errcode='22023';end if;p:=app_private.financial_policy_preview(p_service);perform app_private.financial_require(p_actor,'financial_eligibility.release',(p->>'serviceRegionId')::uuid);select * into cur from app_private.financial_eligibility_decisions where client_service_id=p_service and effective_until is null;if coalesce(cur.decision_version,0)<>p_expected_version then raise exception 'stale_financial_decision' using errcode='40001';end if;update app_private.financial_holds set lifecycle_status='released',released_at=now(),released_by=p_actor,release_reason=p_reason,effective_until=now()where client_service_id=p_service and lifecycle_status='active';n:=app_private.financial_apply_decision(p_service,case when p->>'suggestedStatus'='held'then'hold_recommended'else p->>'suggestedStatus'end,'manual_hold_released','manual_release',p_actor,p_correlation,p||jsonb_build_object('releaseReason',p_reason));insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('financial_eligibility.hold_released',p_actor,'financial-eligibility','client-service',p_service,p_correlation,jsonb_build_object('decisionId',n.financial_eligibility_decision_id,'reason',p_reason));insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('financial-eligibility','FinancialEligibility.HoldReleased',1,'client-service',p_service,jsonb_build_object('clientServiceId',p_service,'decisionId',n.financial_eligibility_decision_id),p_correlation,'user',p_actor::text,now());return to_jsonb(n);end$$;

create or replace function api.financial_eligibility_override_set(p_actor uuid,p_service uuid,p_status text,p_reason text,p_until timestamptz,p_expected_version integer,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare p jsonb;o app_private.financial_eligibility_overrides%rowtype;n app_private.financial_eligibility_decisions%rowtype;cur integer;begin if length(btrim(coalesce(p_reason,'')))<3 then raise exception 'reason_required' using errcode='22023';end if;p:=app_private.financial_policy_preview(p_service);perform app_private.financial_require(p_actor,'financial_eligibility.override',(p->>'serviceRegionId')::uuid);select coalesce(max(version),0)into cur from app_private.financial_eligibility_overrides where client_service_id=p_service;if cur<>p_expected_version then raise exception 'stale_financial_override' using errcode='40001';end if;update app_private.financial_eligibility_overrides set revoked_at=now(),revoked_by=p_actor,revoke_reason='superseded'where client_service_id=p_service and revoked_at is null;insert into app_private.financial_eligibility_overrides(client_service_id,override_status,reason,effective_until,version,created_by)values(p_service,p_status,p_reason,p_until,cur+1,p_actor)returning * into o;p:=app_private.financial_policy_preview(p_service);n:=app_private.financial_apply_decision(p_service,p_status,'manual_override','override',p_actor,p_correlation,p||jsonb_build_object('overrideReason',p_reason));insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('financial_eligibility.override_changed',p_actor,'financial-eligibility','client-service',p_service,p_correlation,jsonb_build_object('status',p_status,'reason',p_reason,'version',o.version));insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('financial-eligibility','FinancialEligibility.OverrideChanged',1,'client-service',p_service,jsonb_build_object('clientServiceId',p_service,'status',p_status,'version',o.version),p_correlation,'user',p_actor::text,now());return to_jsonb(n)||jsonb_build_object('override',to_jsonb(o));end$$;
create or replace function api.financial_eligibility_override_clear(p_actor uuid,p_service uuid,p_reason text,p_expected_version integer,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare p jsonb;n app_private.financial_eligibility_decisions%rowtype;cur integer;begin if length(btrim(coalesce(p_reason,'')))<3 then raise exception 'reason_required' using errcode='22023';end if;p:=app_private.financial_policy_preview(p_service);perform app_private.financial_require(p_actor,'financial_eligibility.override',(p->>'serviceRegionId')::uuid);select coalesce(max(version),0)into cur from app_private.financial_eligibility_overrides where client_service_id=p_service;if cur<>p_expected_version then raise exception 'stale_financial_override' using errcode='40001';end if;update app_private.financial_eligibility_overrides set revoked_at=now(),revoked_by=p_actor,revoke_reason=p_reason where client_service_id=p_service and revoked_at is null;p:=app_private.financial_policy_preview(p_service);n:=app_private.financial_apply_decision(p_service,p->>'suggestedStatus',p->>'reasonCode','policy',p_actor,p_correlation,p);insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('financial_eligibility.override_removed',p_actor,'financial-eligibility','client-service',p_service,p_correlation,jsonb_build_object('reason',p_reason));return to_jsonb(n);end$$;

create or replace function api.financial_eligibility_list(p_actor uuid,p_query jsonb default '{}')returns jsonb language plpgsql security definer set search_path='' as $$begin return jsonb_build_object('items',(select coalesce(jsonb_agg(jsonb_build_object('decisionId',d.financial_eligibility_decision_id,'clientId',d.client_id,'clientServiceId',d.client_service_id,'clientName',c.display_name,'serviceAddress',concat_ws(', ',a.address_line_1,a.suburb),'serviceRegionId',d.service_region_id,'accountStatus',s.derived_status,'freshness',case when s.client_id is null then'missing'when now()>s.stale_after then'stale'else'current'end,'decisionStatus',d.decision_status,'reasonCode',d.reason_code,'decisionVersion',d.decision_version,'activeHold',h.financial_hold_id is not null,'override',case when o.financial_eligibility_override_id is null then null else jsonb_build_object('status',o.override_status,'reason',o.reason,'version',o.version)end,'lastReevaluated',d.created_at)order by d.created_at desc),'[]')from app_private.financial_eligibility_decisions d join app_private.clients c using(client_id)join app_private.client_services cs using(client_service_id)join app_private.service_addresses a on a.service_address_id=cs.service_address_id left join app_private.client_accounting_snapshots s on s.client_id=d.client_id left join app_private.financial_holds h on h.client_service_id=d.client_service_id and h.lifecycle_status='active' left join app_private.financial_eligibility_overrides o on o.client_service_id=d.client_service_id and o.revoked_at is null where d.effective_until is null and app_private.user_has_region_permission(p_actor,'financial_eligibility.read',d.service_region_id)and(nullif(p_query->>'serviceRegionId','')is null or d.service_region_id=(p_query->>'serviceRegionId')::uuid)and(nullif(p_query->>'status','')is null or d.decision_status=p_query->>'status')));end$$;
create or replace function api.financial_eligibility_detail(p_actor uuid,p_service uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare d app_private.financial_eligibility_decisions%rowtype;begin select * into d from app_private.financial_eligibility_decisions where client_service_id=p_service and effective_until is null;if d.financial_eligibility_decision_id is null then raise exception 'not_found' using errcode='P0002';end if;perform app_private.financial_require(p_actor,'financial_eligibility.read',d.service_region_id);return to_jsonb(d)||jsonb_build_object('routeContract',app_private.financial_route_contract(p_service),'routeImpact',app_private.financial_route_impact(p_service,false),'history',(select jsonb_agg(to_jsonb(x)order by decision_version desc)from app_private.financial_eligibility_decisions x where x.client_service_id=p_service),'hold',(select to_jsonb(h)from app_private.financial_holds h where h.client_service_id=p_service order by created_at desc limit 1),'override',(select to_jsonb(o)from app_private.financial_eligibility_overrides o where o.client_service_id=p_service order by created_at desc limit 1));end$$;
create or replace function api.financial_eligibility_batch_start(p_actor uuid,p_body jsonb,p_correlation uuid,p_idempotency text)returns jsonb language plpgsql security definer set search_path='' as $$declare j app_private.financial_eligibility_jobs%rowtype;scope uuid:=nullif(p_body->>'scopeId','')::uuid;begin if p_body->>'scopeType'='region'then perform app_private.financial_require(p_actor,'financial_eligibility.reevaluate',scope);elsif not app_private.user_has_global_permission(p_actor,'financial_eligibility.reevaluate')then raise exception 'permission_denied' using errcode='42501';end if;insert into app_private.financial_eligibility_jobs(scope_type,scope_id,idempotency_key,correlation_id,initiated_by)values(p_body->>'scopeType',scope,p_idempotency,p_correlation,p_actor)on conflict(idempotency_key)do update set idempotency_key=excluded.idempotency_key returning * into j;return to_jsonb(j);end$$;
create or replace function api.financial_eligibility_batch_run(p_job uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare j app_private.financial_eligibility_jobs%rowtype;s record;p jsonb;n app_private.financial_eligibility_decisions%rowtype;processed integer:=0;changed integer:=0;before_id uuid;begin select * into j from app_private.financial_eligibility_jobs where financial_eligibility_job_id=p_job for update;if j.lifecycle_status='succeeded'then return to_jsonb(j);end if;update app_private.financial_eligibility_jobs set lifecycle_status='running',started_at=coalesce(started_at,now())where financial_eligibility_job_id=p_job;for s in select cs.client_service_id from app_private.client_services cs join app_private.service_configurations sc on sc.client_service_id=cs.client_service_id and sc.effective_to is null where(j.scope_type='service'and cs.client_service_id=j.scope_id)or(j.scope_type='client'and cs.client_id=j.scope_id)or(j.scope_type='region'and sc.service_region_id=j.scope_id)or(j.scope_type='stale_review'and exists(select 1 from app_private.client_accounting_snapshots a where a.client_id=cs.client_id and now()>a.stale_after))order by cs.client_service_id limit 500 loop select financial_eligibility_decision_id into before_id from app_private.financial_eligibility_decisions where client_service_id=s.client_service_id and effective_until is null;p:=app_private.financial_policy_preview(s.client_service_id);n:=app_private.financial_apply_decision(s.client_service_id,p->>'suggestedStatus',p->>'reasonCode','policy',j.initiated_by,j.correlation_id,p);processed:=processed+1;if before_id is distinct from n.financial_eligibility_decision_id then changed:=changed+1;end if;end loop;update app_private.financial_eligibility_jobs set lifecycle_status='succeeded',processed_count=processed,changed_count=changed,completed_at=now()where financial_eligibility_job_id=p_job returning * into j;return to_jsonb(j);end$$;
create or replace function api.financial_eligibility_route_contract(p_service uuid)returns jsonb language sql stable security definer set search_path='' as $$select app_private.financial_route_contract(p_service)$$;

revoke all on function app_private.financial_require(uuid,text,uuid),app_private.financial_policy_preview(uuid),app_private.financial_route_contract(uuid),app_private.financial_route_impact(uuid,boolean),app_private.financial_apply_decision(uuid,text,text,text,uuid,uuid,jsonb)from public,anon,authenticated;
revoke all on function api.financial_eligibility_simulate(uuid,uuid),api.financial_eligibility_reevaluate(uuid,uuid,uuid),api.financial_eligibility_hold(uuid,uuid,text,integer,uuid),api.financial_eligibility_release(uuid,uuid,text,integer,uuid),api.financial_eligibility_override_set(uuid,uuid,text,text,timestamptz,integer,uuid),api.financial_eligibility_override_clear(uuid,uuid,text,integer,uuid),api.financial_eligibility_list(uuid,jsonb),api.financial_eligibility_detail(uuid,uuid),api.financial_eligibility_batch_start(uuid,jsonb,uuid,text),api.financial_eligibility_batch_run(uuid),api.financial_eligibility_route_contract(uuid)from public,anon,authenticated;
grant execute on function api.financial_eligibility_simulate(uuid,uuid),api.financial_eligibility_reevaluate(uuid,uuid,uuid),api.financial_eligibility_hold(uuid,uuid,text,integer,uuid),api.financial_eligibility_release(uuid,uuid,text,integer,uuid),api.financial_eligibility_override_set(uuid,uuid,text,text,timestamptz,integer,uuid),api.financial_eligibility_override_clear(uuid,uuid,text,integer,uuid),api.financial_eligibility_list(uuid,jsonb),api.financial_eligibility_detail(uuid,uuid),api.financial_eligibility_batch_start(uuid,jsonb,uuid,text)to service_role;
grant execute on function api.financial_eligibility_batch_run(uuid),api.financial_eligibility_route_contract(uuid)to service_role;

-- Route Planning asks only the narrow contract. Held work is represented explicitly and
-- generated Draft capacity is recomputed from the stops actually accepted.
create or replace function app_private.route_enforce_financial_contract()returns trigger language plpgsql security definer set search_path='' as $$declare contract jsonb;begin contract:=app_private.financial_route_contract(new.client_service_id);if contract->>'decisionStatus'='held'then insert into app_private.unassigned_route_services(route_version_id,client_service_id,service_configuration_id,service_address_id,reason_code,constraint_detail,remediation,service_snapshot)values(new.route_version_id,new.client_service_id,new.service_configuration_id,new.service_address_id,'financial_hold',jsonb_build_object('decisionVersion',(contract->>'decisionVersion')::integer),'Review or release the service financial hold before regenerating.',jsonb_build_object('clientServiceId',new.client_service_id))on conflict(route_version_id,client_service_id)do nothing;return null;end if;return new;end$$;
create trigger planned_stop_financial_contract before insert on app_private.planned_route_stops for each row execute function app_private.route_enforce_financial_contract();
create or replace function app_private.route_recompute_generated_totals()returns trigger language plpgsql security definer set search_path='' as $$begin new.planned_capacity_units:=coalesce((select sum(drum_units)from app_private.planned_route_stops where planned_route_id=new.planned_route_id),0);new.planned_duration_minutes:=coalesce((select sum(planned_duration_minutes+5)from app_private.planned_route_stops where planned_route_id=new.planned_route_id),0);return new;end$$;
create trigger planned_route_recompute_financial_totals before update of planned_capacity_units,planned_duration_minutes on app_private.planned_routes for each row execute function app_private.route_recompute_generated_totals();
revoke all on function app_private.route_enforce_financial_contract(),app_private.route_recompute_generated_totals()from public,anon,authenticated;

-- Extend the existing Needs Attention queue with a constrained financial source.
alter table app_private.needs_attention_items drop constraint needs_attention_items_source_type_check;
alter table app_private.needs_attention_items drop constraint needs_attention_items_source_id_fkey;
alter table app_private.needs_attention_items alter column source_id drop not null;
alter table app_private.needs_attention_items add column financial_decision_id uuid references app_private.financial_eligibility_decisions;
alter table app_private.needs_attention_items add constraint needs_attention_items_source_type_check check(source_type in('operational_fact','financial_eligibility'));
alter table app_private.needs_attention_items add constraint needs_attention_items_source_shape_check check((source_type='operational_fact'and source_id is not null and financial_decision_id is null)or(source_type='financial_eligibility'and source_id is null and financial_decision_id is not null));
create unique index needs_attention_financial_decision_idx on app_private.needs_attention_items(financial_decision_id)where financial_decision_id is not null;
create or replace function app_private.financial_attention_after_decision()returns trigger language plpgsql security definer set search_path='' as $$declare impact jsonb;begin impact:=app_private.financial_route_impact(new.client_service_id,false);if new.decision_status in('held','manual_review','unknown')and(impact->>'reviewRequired')::boolean then insert into app_private.needs_attention_items(source_type,source_id,financial_decision_id,service_region_id,severity)values('financial_eligibility',null,new.financial_eligibility_decision_id,new.service_region_id,'warning')on conflict(financial_decision_id)do nothing;end if;return new;end$$;
create trigger financial_decision_needs_attention after insert on app_private.financial_eligibility_decisions for each row execute function app_private.financial_attention_after_decision();
create or replace function api.needs_attention_list(p_actor_id uuid,p_region_id uuid,p_status text default null)returns jsonb language plpgsql security definer set search_path='' as $$begin perform app_private.require_intelligence_access(p_actor_id,'needs_attention.read',p_region_id);return coalesce((select jsonb_agg(to_jsonb(n)||jsonb_build_object('factType',case when n.source_type='financial_eligibility'then'financial_eligibility'else f.fact_type end,'summary',case when n.source_type='financial_eligibility'then'Financial eligibility changed after route publication or handoff'else f.summary end,'confidence',case when n.source_type='financial_eligibility'then'high'else f.confidence end,'vehicleId',f.vehicle_id,'routeOperationId',f.route_operation_id,'clientServiceId',d.client_service_id)order by n.created_at desc)from app_private.needs_attention_items n left join app_private.derived_operational_facts f on f.operational_fact_id=n.source_id left join app_private.financial_eligibility_decisions d on d.financial_eligibility_decision_id=n.financial_decision_id where n.service_region_id=p_region_id and(p_status is null or n.lifecycle_status=p_status)),'[]');end$$;
create or replace function api.needs_attention_detail(p_actor_id uuid,p_item_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare n app_private.needs_attention_items%rowtype;begin select * into n from app_private.needs_attention_items where needs_attention_item_id=p_item_id;if n.needs_attention_item_id is null then raise exception 'not found' using errcode='P0002';end if;perform app_private.require_intelligence_access(p_actor_id,'needs_attention.read',n.service_region_id);return to_jsonb(n)||case when n.source_type='financial_eligibility'then jsonb_build_object('financialDecision',(select to_jsonb(d)-'evidence'from app_private.financial_eligibility_decisions d where d.financial_eligibility_decision_id=n.financial_decision_id))else jsonb_build_object('fact',(select to_jsonb(f)from app_private.derived_operational_facts f where f.operational_fact_id=n.source_id))end;end$$;
revoke all on function app_private.financial_attention_after_decision()from public,anon,authenticated;

create or replace function app_private.queue_financial_reevaluation_from_accounting_event()returns trigger language plpgsql security definer set search_path='' as $$begin if new.event_name in('Accounting.AccountStatusChanged','Accounting.AccountingDataStale','Accounting.ExceptionChanged')then insert into app_private.financial_eligibility_jobs(scope_type,scope_id,idempotency_key,correlation_id,initiated_by)values('client',new.aggregate_id,'accounting-event:'||new.event_id,new.correlation_id,null)on conflict(idempotency_key)do nothing;end if;return new;end$$;
create trigger accounting_event_financial_reevaluation after insert on app_private.outbox_events for each row when(new.producer_module='accounting')execute function app_private.queue_financial_reevaluation_from_accounting_event();
revoke all on function app_private.queue_financial_reevaluation_from_accounting_event()from public,anon,authenticated;

create or replace function app_private.financial_route_impact(p_service uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare stale_count integer;published_count integer;operation_count integer;begin update app_private.route_versions v set is_stale=true,stale_reason='financial_eligibility_changed',updated_at=now()where v.version_status in('draft','ready')and exists(select 1 from app_private.planned_route_stops s where s.route_version_id=v.route_version_id and s.client_service_id=p_service);get diagnostics stale_count=row_count;select count(*)into published_count from app_private.planned_route_stops s join app_private.route_versions v using(route_version_id)where s.client_service_id=p_service and v.version_status='published';select count(*)into operation_count from app_private.route_operation_stops s join app_private.planned_route_stops ps on ps.planned_route_stop_id=s.source_planned_route_stop_id join app_private.route_operations o using(route_operation_id)where ps.client_service_id=p_service and o.lifecycle_status not in('completed','cancelled','superseded','archived');return jsonb_build_object('draftReadyMarkedStale',stale_count,'publishedRoutesProtected',published_count,'activeOperationsProtected',operation_count,'reviewRequired',published_count+operation_count>0);end$$;

create or replace function app_private.financial_apply_decision(p_service uuid,p_status text,p_reason text,p_source text,p_actor uuid,p_correlation uuid,p_evidence jsonb)returns app_private.financial_eligibility_decisions language plpgsql security definer set search_path='' as $$declare old app_private.financial_eligibility_decisions%rowtype;n app_private.financial_eligibility_decisions%rowtype;svc app_private.client_services%rowtype;region uuid;policy uuid;impact jsonb;begin select * into svc from app_private.client_services where client_service_id=p_service;select service_region_id into region from app_private.service_configurations where client_service_id=p_service and effective_to is null order by effective_from desc limit 1;select financial_eligibility_policy_version_id into policy from app_private.financial_eligibility_policy_versions where lifecycle_status='active' order by created_at desc limit 1;select * into old from app_private.financial_eligibility_decisions where client_service_id=p_service and effective_until is null for update;if old.financial_eligibility_decision_id is not null and old.decision_status=p_status and old.reason_code=p_reason and old.evidence=p_evidence then return old;end if;update app_private.financial_eligibility_decisions set effective_until=now()where financial_eligibility_decision_id=old.financial_eligibility_decision_id;insert into app_private.financial_eligibility_decisions(client_id,client_service_id,service_region_id,accounting_snapshot_client_id,policy_version_id,decision_version,decision_status,reason_code,evidence,decision_source,actor_id,correlation_id,supersedes_decision_id)values(svc.client_id,p_service,region,case when exists(select 1 from app_private.client_accounting_snapshots where client_id=svc.client_id)then svc.client_id end,policy,coalesce(old.decision_version,0)+1,p_status,p_reason,p_evidence,p_source,p_actor,p_correlation,old.financial_eligibility_decision_id)returning * into n;impact:=app_private.financial_route_impact(p_service);insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('financial-eligibility','FinancialEligibility.DecisionChanged',1,'client-service',p_service,jsonb_build_object('clientServiceId',p_service,'decisionId',n.financial_eligibility_decision_id,'status',p_status,'reasonCode',p_reason,'version',n.decision_version),p_correlation,case when p_actor is null then'system'else'user'end,p_actor::text,now());return n;end$$;

create or replace function api.financial_eligibility_simulate(p_actor uuid,p_service uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare preview jsonb;begin preview:=app_private.financial_policy_preview(p_service);perform app_private.financial_require(p_actor,'financial_eligibility.review',(preview->>'serviceRegionId')::uuid);return preview||jsonb_build_object('committed',false);end$$;
create or replace function api.financial_eligibility_reevaluate(p_actor uuid,p_service uuid,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare preview jsonb;n app_private.financial_eligibility_decisions%rowtype;begin preview:=app_private.financial_policy_preview(p_service);perform app_private.financial_require(p_actor,'financial_eligibility.reevaluate',(preview->>'serviceRegionId')::uuid);n:=app_private.financial_apply_decision(p_service,preview->>'suggestedStatus',preview->>'reasonCode','policy',p_actor,p_correlation,preview);insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('financial_eligibility.reevaluated',p_actor,'financial-eligibility','client-service',p_service,p_correlation,jsonb_build_object('decisionId',n.financial_eligibility_decision_id,'status',n.decision_status));return to_jsonb(n)||jsonb_build_object('routeImpact',app_private.financial_route_impact(p_service));end$$;
create or replace function api.financial_eligibility_batch_start(p_actor uuid,p_body jsonb,p_correlation uuid,p_idempotency text)returns jsonb language plpgsql security definer set search_path='' as $$declare j app_private.financial_eligibility_jobs%rowtype;region uuid;begin region:=nullif(p_body->>'scopeId','')::uuid;if p_body->>'scopeType'='region'then perform app_private.financial_require(p_actor,'financial_eligibility.reevaluate',region);elsif not app_private.user_has_global_permission(p_actor,'financial_eligibility.reevaluate')then raise exception 'permission_denied' using errcode='42501';end if;insert into app_private.financial_eligibility_jobs(scope_type,scope_id,idempotency_key,correlation_id,initiated_by)values(p_body->>'scopeType',region,p_idempotency,p_correlation,p_actor)on conflict(idempotency_key)do update set idempotency_key=excluded.idempotency_key returning * into j;return to_jsonb(j);end$$;
create or replace function api.financial_eligibility_batch_run(p_job uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare j app_private.financial_eligibility_jobs%rowtype;s record;p jsonb;n app_private.financial_eligibility_decisions%rowtype;processed integer:=0;changed integer:=0;before_id uuid;begin select * into j from app_private.financial_eligibility_jobs where financial_eligibility_job_id=p_job for update;if j.lifecycle_status='succeeded'then return to_jsonb(j);end if;update app_private.financial_eligibility_jobs set lifecycle_status='running',started_at=coalesce(started_at,now())where financial_eligibility_job_id=p_job;for s in select cs.client_service_id from app_private.client_services cs join app_private.service_configurations sc on sc.client_service_id=cs.client_service_id and sc.effective_to is null where(j.scope_type='service'and cs.client_service_id=j.scope_id)or(j.scope_type='client'and cs.client_id=j.scope_id)or(j.scope_type='region'and sc.service_region_id=j.scope_id)or(j.scope_type='stale_review'and exists(select 1 from app_private.client_accounting_snapshots a where a.client_id=cs.client_id and now()>a.stale_after))order by cs.client_service_id limit 500 loop select financial_eligibility_decision_id into before_id from app_private.financial_eligibility_decisions where client_service_id=s.client_service_id and effective_until is null;p:=app_private.financial_policy_preview(s.client_service_id);n:=app_private.financial_apply_decision(s.client_service_id,p->>'suggestedStatus',p->>'reasonCode','policy',j.initiated_by,j.correlation_id,p);processed:=processed+1;if before_id is distinct from n.financial_eligibility_decision_id then changed:=changed+1;end if;end loop;update app_private.financial_eligibility_jobs set lifecycle_status='succeeded',processed_count=processed,changed_count=changed,completed_at=now()where financial_eligibility_job_id=p_job returning * into j;return to_jsonb(j);end$$;

create or replace function api.financial_eligibility_hold(p_actor uuid,p_service uuid,p_reason text,p_expected_version integer,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare preview jsonb;cur app_private.financial_eligibility_decisions%rowtype;n app_private.financial_eligibility_decisions%rowtype;h app_private.financial_holds%rowtype;begin if length(btrim(coalesce(p_reason,'')))<3 then raise exception 'reason_required' using errcode='22023';end if;preview:=app_private.financial_policy_preview(p_service);perform app_private.financial_require(p_actor,'financial_eligibility.hold',(preview->>'serviceRegionId')::uuid);select * into cur from app_private.financial_eligibility_decisions where client_service_id=p_service and effective_until is null;if coalesce(cur.decision_version,0)<>p_expected_version then raise exception 'stale_financial_decision' using errcode='40001';end if;n:=app_private.financial_apply_decision(p_service,'held','manual_financial_hold','manual_hold',p_actor,p_correlation,preview||jsonb_build_object('manualReason',p_reason));insert into app_private.financial_holds(client_service_id,source_decision_id,lifecycle_status,reason_code,created_by)values(p_service,n.financial_eligibility_decision_id,'active','manual_financial_hold',p_actor)returning * into h;insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('financial_eligibility.hold_activated',p_actor,'financial-eligibility','client-service',p_service,p_correlation,jsonb_build_object('decisionId',n.financial_eligibility_decision_id,'holdId',h.financial_hold_id,'reason',p_reason));insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('financial-eligibility','FinancialEligibility.HoldActivated',1,'client-service',p_service,jsonb_build_object('clientServiceId',p_service,'decisionId',n.financial_eligibility_decision_id,'holdId',h.financial_hold_id),p_correlation,'user',p_actor::text,now());return to_jsonb(n)||jsonb_build_object('hold',to_jsonb(h),'routeImpact',app_private.financial_route_impact(p_service));end$$;
create or replace function api.financial_eligibility_release(p_actor uuid,p_service uuid,p_reason text,p_expected_version integer,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare preview jsonb;cur app_private.financial_eligibility_decisions%rowtype;n app_private.financial_eligibility_decisions%rowtype;begin if length(btrim(coalesce(p_reason,'')))<3 then raise exception 'reason_required' using errcode='22023';end if;preview:=app_private.financial_policy_preview(p_service);perform app_private.financial_require(p_actor,'financial_eligibility.release',(preview->>'serviceRegionId')::uuid);select * into cur from app_private.financial_eligibility_decisions where client_service_id=p_service and effective_until is null;if coalesce(cur.decision_version,0)<>p_expected_version then raise exception 'stale_financial_decision' using errcode='40001';end if;update app_private.financial_holds set lifecycle_status='released',released_at=now(),released_by=p_actor,release_reason=p_reason,effective_until=now()where client_service_id=p_service and lifecycle_status='active';n:=app_private.financial_apply_decision(p_service,case when preview->>'suggestedStatus'='held'then'hold_recommended'else preview->>'suggestedStatus'end,'manual_hold_released','manual_release',p_actor,p_correlation,preview||jsonb_build_object('releaseReason',p_reason));insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('financial_eligibility.hold_released',p_actor,'financial-eligibility','client-service',p_service,p_correlation,jsonb_build_object('decisionId',n.financial_eligibility_decision_id,'reason',p_reason));insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('financial-eligibility','FinancialEligibility.HoldReleased',1,'client-service',p_service,jsonb_build_object('clientServiceId',p_service,'decisionId',n.financial_eligibility_decision_id),p_correlation,'user',p_actor::text,now());return to_jsonb(n);end$$;
-- Preserve the drafted one-argument body under a non-contract name. Calls with one
-- argument now resolve to the authoritative two-argument function's default.
alter function app_private.financial_route_impact(uuid) rename to financial_route_impact_legacy;
alter table app_private.financial_eligibility_decisions drop constraint financial_eligibility_decisions_check;
alter table app_private.financial_eligibility_decisions add constraint financial_eligibility_decisions_effective_period_check check(effective_until is null or effective_until>=effective_from);
create or replace function app_private.financial_apply_decision(p_service uuid,p_status text,p_reason text,p_source text,p_actor uuid,p_correlation uuid,p_evidence jsonb)returns app_private.financial_eligibility_decisions language plpgsql security definer set search_path='' as $$declare old app_private.financial_eligibility_decisions%rowtype;n app_private.financial_eligibility_decisions%rowtype;svc app_private.client_services%rowtype;region uuid;policy uuid;begin select * into svc from app_private.client_services where client_service_id=p_service;select service_region_id into region from app_private.service_configurations where client_service_id=p_service and effective_to is null order by effective_from desc limit 1;select financial_eligibility_policy_version_id into policy from app_private.financial_eligibility_policy_versions where lifecycle_status='active' order by created_at desc limit 1;select * into old from app_private.financial_eligibility_decisions where client_service_id=p_service and effective_until is null for update;if old.financial_eligibility_decision_id is not null and old.decision_status=p_status and old.reason_code=p_reason and old.evidence=p_evidence then return old;end if;update app_private.financial_eligibility_decisions set effective_until=now()where financial_eligibility_decision_id=old.financial_eligibility_decision_id;insert into app_private.financial_eligibility_decisions(client_id,client_service_id,service_region_id,accounting_snapshot_client_id,policy_version_id,decision_version,decision_status,reason_code,evidence,decision_source,actor_id,correlation_id,supersedes_decision_id)values(svc.client_id,p_service,region,case when exists(select 1 from app_private.client_accounting_snapshots where client_id=svc.client_id)then svc.client_id end,policy,coalesce(old.decision_version,0)+1,p_status,p_reason,p_evidence,p_source,p_actor,p_correlation,old.financial_eligibility_decision_id)returning * into n;perform app_private.financial_route_impact(p_service,true);insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('financial-eligibility','FinancialEligibility.DecisionChanged',1,'client-service',p_service,jsonb_build_object('clientServiceId',p_service,'decisionId',n.financial_eligibility_decision_id,'status',p_status,'reasonCode',p_reason,'version',n.decision_version),p_correlation,case when p_actor is null then'system'else'user'end,p_actor::text,now());return n;end$$;
